# frozen_string_literal: true

##
# These examples walk you through operations specifically related to search

require_relative 'client_initialization'

##
# Create a collection
schema = {
  'name' => 'companies',
  'fields' => [
    {
      'name' => 'company_name',
      'type' => 'string'
    },
    {
      'name' => 'num_employees',
      'type' => 'int32'
    },
    {
      'name' => 'country',
      'type' => 'string',
      'facet' => true
    }
  ],
  'default_sorting_field' => 'num_employees'
}

# Delete the collection if it already exists
begin
  @typesense.collections['companies'].delete
rescue Typesense::Error::ObjectNotFound
end

# Now create the collection
@typesense.collections.create(schema)

# Let's create a couple documents for us to use in our search examples
@typesense.collections['companies'].documents.create(
  'id' => '124',
  'company_name' => 'Stark Industries',
  'num_employees' => 5215,
  'country' => 'USA'
)

@typesense.collections['companies'].documents.create(
  'id' => '127',
  'company_name' => 'Stark Corp',
  'num_employees' => 1031,
  'country' => 'USA'
)

@typesense.collections['companies'].documents.create(
  'id' => '125',
  'company_name' => 'Acme Corp',
  'num_employees' => 1002,
  'country' => 'France'
)

@typesense.collections['companies'].documents.create(
  'id' => '126',
  'company_name' => 'Doofenshmirtz Inc',
  'num_employees' => 2,
  'country' => 'Tri-State Area'
)

##
# Search for documents
results = @typesense.collections['companies'].documents.search(
  'q' => 'Stark',
  'query_by' => 'company_name'
)
ap results

##
# Search for more documents
results = @typesense.collections['companies'].documents.search(
  'q' => 'Inc',
  'query_by' => 'company_name',
  'filter_by' => 'num_employees:<100',
  'sort_by' => 'num_employees:desc'
)
ap results

##
# Search for more multiple documents
results = @typesense.multi_search.perform(
  {
    searches: [
      {
        'q' => 'Inc',
        'filter_by' => 'num_employees:<100',
        'sort_by' => 'num_employees:desc'
      },
      {
        'q' => 'Stark'
      }
    ]
  },
  {
    # Parameters that are common to all searches, can be mentioned here
    'collection' => 'companies',
    'query_by' => 'company_name'
  }
)
ap results

##
# Search for more documents
results = @typesense.collections['companies'].documents.search(
  'q' => 'Non-existent',
  'query_by' => 'company_name',
  # Optionally add a user id if you use Analytics & Query Suggestions
  'x-typesense-user-id' => 42
)
ap results

##
# Cleanup
# Drop the collection
@typesense.collections['companies'].delete

# frozen_string_literal: true

module Typesense
  class MultiSearch
    RESOURCE_PATH = '/multi_search'

    def initialize(api_call)
      @api_call = api_call
    end

    def perform(searches, query_params = {})
      @api_call.post(RESOURCE_PATH, searches, query_params)
    end
  end
end

# frozen_string_literal: true

module Typesense
  class NlSearchModels
    RESOURCE_PATH = '/nl_search_models'

    def initialize(api_call)
      @api_call = api_call
      @nl_search_models = {}
    end

    def create(schema)
      @api_call.post(RESOURCE_PATH, schema)
    end

    def retrieve
      @api_call.get(RESOURCE_PATH)
    end

    def [](model_id)
      @nl_search_models[model_id] ||= NlSearchModel.new(model_id, @api_call)
    end
  end
end

# frozen_string_literal: true

module Typesense
  class NlSearchModel
    def initialize(model_id, api_call)
      @model_id = model_id
      @api_call = api_call
    end

    def retrieve
      @api_call.get(endpoint_path)
    end

    def update(update_schema)
      @api_call.put(endpoint_path, update_schema)
    end

    def delete
      @api_call.delete(endpoint_path)
    end

    private

    def endpoint_path
      "#{NlSearchModels::RESOURCE_PATH}/#{URI.encode_www_form_component(@model_id)}"
    end
  end
end
